(function(){
  var out = document.getElementById('r32-out');
  var inp = document.getElementById('r32-inp');
  var status = document.getElementById('r32-status');
  var runBtn = document.getElementById('r32-run');
  var clearBtn = document.getElementById('r32-clear');
  var webR = null, ready = false;

  function print(txt, col) {
    var s = document.createElement('span');
    s.style.color = col || '#b5f0c8';
    s.textContent = txt + '\n';
    out.appendChild(s);
    out.scrollTop = out.scrollHeight;
  }

  clearBtn.onclick = function() { out.innerHTML = ''; };

  document.querySelectorAll('.r32-ex').forEach(function(btn) {
    btn.style.cssText = 'padding:2px 7px;border-radius:4px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.05);color:rgba(180,220,255,.6);font-size:9px;cursor:pointer;font-family:Courier New,monospace';
    btn.onclick = function() { inp.value = btn.getAttribute('data-v'); };
  });

  async function runCode() {
    var code = inp.value.trim();
    if (!code) return;
    print('> ' + code, 'rgba(126,200,227,.8)');
    inp.value = '';
    if (!ready) { print('[R non prêt — patientez]', '#f5a623'); return; }
    try {
      var res = await webR.evalRString('paste(capture.output(' + code + '), collapse="\\n")');
      print(res || '[invisible]');
    } catch(e) {
      print('Erreur : ' + e.message, '#f08080');
    }
  }

  runBtn.onclick = runCode;
  inp.addEventListener('keydown', function(e) { if (e.key === 'Enter') runCode(); });

  import('https://webr.r-wasm.org/latest/webr.mjs').then(async function(m) {
    status.textContent = 'Initialisation…';
    status.style.color = '#f5a623';
    try {
      webR = new m.WebR();
      await webR.init();
      ready = true;
      status.textContent = 'R prêt ✓';
      status.style.color = '#38b49a';
      print('WebR prêt. Tapez du code R ci-dessous.', '#38b49a');
      print('> x <- c(1,2,3,4,5)', 'rgba(126,200,227,.6)');
      print('[1] objet créé', 'rgba(200,200,200,.5)');
    } catch(e) {
      status.textContent = 'WebR non disponible';
      status.style.color = '#f08080';
      print('WebR non chargé (réseau requis).', '#f08080');
      print('Mode démo — utilisez les boutons exemples pour voir la syntaxe R.', '#f5a623');
      // Fallback simulator for basic expressions
      ready = false;
      runBtn.onclick = function() {
        var code = inp.value.trim(); if (!code) return;
        print('> ' + code, 'rgba(126,200,227,.8)'); inp.value = '';
        var res = evalSimple(code);
        print(res, res.startsWith('Erreur') ? '#f08080' : '#b5f0c8');
      };
    }
  }).catch(function() {
    status.textContent = 'Hors-ligne';
    status.style.color = '#f08080';
    print('WebR non disponible hors ligne.', '#f08080');
  });

  function evalSimple(code) {
    try {
      var clean = code.replace(/<-/g,'=').replace(/\^/g,'**')
        .replace(/\bc\(/g,'[').replace(/\)/g,']')
        .replace(/\bmean\[([^\]]+)\]/g, function(_,a){var v=a.split(',').map(Number);return (v.reduce(function(s,x){return s+x;},0)/v.length).toFixed(4);})
        .replace(/\bsd\[([^\]]+)\]/g, function(_,a){var v=a.split(',').map(Number);var m=v.reduce(function(s,x){return s+x;},0)/v.length;return Math.sqrt(v.reduce(function(s,x){return s+(x-m)*(x-m);},0)/(v.length-1)).toFixed(4);})
        .replace(/\bfactorial\[(\d+)\]/g,function(_,n){var r=1;for(var i=2;i<=+n;i++)r*=i;return r;});
      return '[1] ' + eval(clean);
    } catch(e) { return 'Erreur : ' + e.message; }
  }
})();

(function(){
  var N = 10;
  var g = [[],[],[]];
  var colors = ['#38b49a','#5b9cf6','#e879a0'];
  var colIds = [['mu1','sig1'],['mu2','sig2'],['mu3','sig3']];

  function randn(mu, sg) {
    var u = Math.max(Math.random(), 1e-10), v = Math.random();
    return mu + sg * Math.sqrt(-2*Math.log(u)) * Math.cos(2*Math.PI*v);
  }
  function mean(a) { return a.reduce(function(s,x){return s+x;},0) / a.length; }

  function getParam(id) { return parseFloat(document.getElementById('a33-sl-'+id).value); }

  function genAll() {
    for (var gi = 0; gi < 3; gi++) {
      var mu = getParam(colIds[gi][0]), sg = getParam(colIds[gi][1]);
      g[gi] = [];
      for (var i = 0; i < N; i++) g[gi].push(parseFloat(randn(mu,sg).toFixed(2)));
      document.getElementById('a33-'+colIds[gi][0]).textContent = mu;
      document.getElementById('a33-'+colIds[gi][1]).textContent = sg;
    }
  }

  function drawBoxplots() {
    var cvs = document.getElementById('a33-cvs');
    if (!cvs) return;
    var W = cvs.parentElement.clientWidth - 16 || 300, H = 120;
    cvs.width = W; cvs.height = H;
    var ctx = cvs.getContext('2d');
    ctx.clearRect(0,0,W,H);
    var all = g[0].concat(g[1],g[2]);
    var mn = Math.min.apply(null,all)-1, mx = Math.max.apply(null,all)+1;
    var PL=32,PR=8,PT=10,PB=22;
    var GW = (W-PL-PR)/3;
    function tx(i) { return PL + (i+0.5)*GW; }
    function ty(v) { return PT + (1-(v-mn)/(mx-mn))*(H-PT-PB); }
    // gridlines + y labels
    for (var i=0;i<=4;i++) {
      var yv = mn+(mx-mn)*i/4;
      ctx.strokeStyle='rgba(255,255,255,.06)';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(PL,ty(yv));ctx.lineTo(W-PR,ty(yv));ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,.3)';ctx.font='8px monospace';ctx.textAlign='right';
      ctx.fillText(yv.toFixed(1),PL-2,ty(yv)+3);
    }
    // boxplots
    g.forEach(function(arr,gi) {
      var s = arr.slice().sort(function(a,b){return a-b;});
      var q1=s[Math.floor(s.length*0.25)], med=s[Math.floor(s.length*0.5)], q3=s[Math.floor(s.length*0.75)];
      var iqr=q3-q1, lo=Math.max(mn,q1-1.5*iqr), hi=Math.min(mx,q3+1.5*iqr);
      var xc=tx(gi), bw=GW*0.45, col=colors[gi];
      ctx.strokeStyle=col; ctx.lineWidth=1.5;
      // whiskers
      ctx.beginPath();ctx.moveTo(xc,ty(lo));ctx.lineTo(xc,ty(hi));ctx.stroke();
      ctx.beginPath();ctx.moveTo(xc-bw/4,ty(lo));ctx.lineTo(xc+bw/4,ty(lo));ctx.stroke();
      ctx.beginPath();ctx.moveTo(xc-bw/4,ty(hi));ctx.lineTo(xc+bw/4,ty(hi));ctx.stroke();
      // box
      ctx.fillStyle=col+'22'; ctx.fillRect(xc-bw/2,ty(q3),bw,ty(q1)-ty(q3));
      ctx.strokeRect(xc-bw/2,ty(q3),bw,ty(q1)-ty(q3));
      // median
      ctx.strokeStyle='#fff'; ctx.lineWidth=2;
      ctx.beginPath();ctx.moveTo(xc-bw/2,ty(med));ctx.lineTo(xc+bw/2,ty(med));ctx.stroke();
      // mean dot
      ctx.fillStyle=col; ctx.beginPath(); ctx.arc(xc,ty(mean(arr)),3,0,2*Math.PI); ctx.fill();
      // label
      ctx.fillStyle='rgba(255,255,255,.45)';ctx.font='9px system-ui';ctx.textAlign='center';
      ctx.fillText(['A','B','C'][gi],xc,H-5);
    });
  }

  function computeANOVA() {
    var all = g[0].concat(g[1],g[2]), K=3, n=N, tot=all.length;
    var gm = mean(all);
    var gMeans = g.map(mean);
    var ssB = n * gMeans.reduce(function(s,m){return s+(m-gm)*(m-gm);},0);
    var ssW = g.reduce(function(s,arr){return s+arr.reduce(function(s2,x){return s2+(x-mean(arr))*(x-mean(arr));},0);},0);
    var dfB=K-1, dfW=tot-K;
    var msB=ssB/dfB, msW=ssW/dfW, F=msB/msW;
    // p-value via F approximation
    var p = Math.exp(-0.717*F - 0.416*F*F/dfW);
    p = Math.max(0.0001, Math.min(0.9999, p));
    var sig = p<0.001?'***' : p<0.01?'**' : p<0.05?'*':'NS';
    var el = document.getElementById('a33-res');
    if (!el) return;
    el.textContent =
      'Tableau ANOVA (n='+N+'/groupe, K=3)\n'+
      ''.padEnd(40,'─')+'\n'+
      '              SS      df     MS       F\n'+
      'Entre grp  '+ssB.toFixed(2).padStart(7)+' '+dfB.toString().padStart(4)+'  '+msB.toFixed(2).padStart(6)+'  '+F.toFixed(3)+'\n'+
      'Intra grp  '+ssW.toFixed(2).padStart(7)+' '+dfW.toString().padStart(4)+'  '+msW.toFixed(2).padStart(6)+'\n'+
      ''.padEnd(40,'─')+'\n'+
      'F('+dfB+','+dfW+') = '+F.toFixed(3)+'   p ≈ '+p.toFixed(4)+'  '+sig+'\n'+
      'Moyennes : A='+gMeans[0].toFixed(2)+'  B='+gMeans[1].toFixed(2)+'  C='+gMeans[2].toFixed(2);
    el.style.color = p<0.05 ? '#7de8a0' : '#f5a060';

    var mu1=getParam('mu1'),mu2=getParam('mu2'),mu3=getParam('mu3');
    var s1=getParam('sig1'),s2=getParam('sig2'),s3=getParam('sig3');
    var rc = document.getElementById('a33-code');
    if (rc) rc.textContent =
      'Y <- c(rnorm(10,'+mu1+','+s1+'), rnorm(10,'+mu2+','+s2+'), rnorm(10,'+mu3+','+s3+'))\n'+
      'X <- factor(rep(c("A","B","C"), each=10))\n'+
      'summary(aov(Y ~ X))\n'+
      'TukeyHSD(aov(Y ~ X))';
  }

  function update() { genAll(); drawBoxplots(); computeANOVA(); }

  // wire sliders
  ['mu1','sig1','mu2','sig2','mu3','sig3'].forEach(function(id) {
    var sl = document.getElementById('a33-sl-'+id);
    if (sl) sl.addEventListener('input', update);
  });
  document.getElementById('a33-regen').addEventListener('click', update);

  update();

  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(function() { drawBoxplots(); }).observe(document.getElementById('a33-cvs').parentElement);
  }
})();

(function(){
  var X=[], Y=[];

  function randn(mu,sg) {
    var u=Math.max(Math.random(),1e-10), v=Math.random();
    return mu + sg*Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  }
  function getVal(id) { return parseFloat(document.getElementById('rl34-'+id).value); }

  function gen() {
    var b0=getVal('b0'), b1=getVal('b1'), sg=getVal('sg');
    X=[]; Y=[];
    for (var i=0;i<30;i++) { var x=randn(10,4); X.push(x); Y.push(b0+b1*x+randn(0,sg)); }
  }

  function fit() {
    var n=X.length;
    var mx=X.reduce(function(s,v){return s+v;},0)/n;
    var my=Y.reduce(function(s,v){return s+v;},0)/n;
    var sxx=X.reduce(function(s,v){return s+(v-mx)*(v-mx);},0);
    var sxy=X.reduce(function(s,v,i){return s+(v-mx)*(Y[i]-my);},0);
    var b1h=sxy/sxx, b0h=my-b1h*mx;
    var yhat=X.map(function(v){return b0h+b1h*v;});
    var res=Y.map(function(v,i){return v-yhat[i];});
    var ssr=res.reduce(function(s,v){return s+v*v;},0);
    var sst=Y.reduce(function(s,v){return s+(v-my)*(v-my);},0);
    var r2=1-ssr/sst, se=Math.sqrt(ssr/(n-2));
    var seb1=se/Math.sqrt(sxx), t=b1h/seb1;
    return {b0:b0h, b1:b1h, r2:r2, se:se, t:t, res:res, yhat:yhat};
  }

  function draw(f) {
    // Main scatter
    var cvs=document.getElementById('rl34-cvs');
    if (!cvs) return;
    var W=cvs.parentElement.clientWidth-16||360, H=140;
    cvs.width=W; cvs.height=H;
    var ctx=cvs.getContext('2d');
    ctx.clearRect(0,0,W,H);
    var PL=32,PR=8,PT=8,PB=20;
    var xmn=Math.min.apply(null,X)-1, xmx=Math.max.apply(null,X)+1;
    var ymn=Math.min.apply(null,Y)-1, ymx=Math.max.apply(null,Y)+1;
    function tx(v){return PL+(v-xmn)/(xmx-xmn)*(W-PL-PR);}
    function ty(v){return PT+(1-(v-ymn)/(ymx-ymn))*(H-PT-PB);}
    // grid
    for(var i=0;i<=4;i++){
      var yv=ymn+(ymx-ymn)*i/4;
      ctx.strokeStyle='rgba(255,255,255,.05)';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(PL,ty(yv));ctx.lineTo(W-PR,ty(yv));ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,.25)';ctx.font='8px monospace';ctx.textAlign='right';
      ctx.fillText(yv.toFixed(1),PL-2,ty(yv)+3);
    }
    // points
    X.forEach(function(x,i){
      ctx.fillStyle='rgba(91,156,246,.65)';ctx.beginPath();ctx.arc(tx(x),ty(Y[i]),2.5,0,2*Math.PI);ctx.fill();
    });
    // true line
    ctx.strokeStyle='rgba(244,114,182,.4)'; ctx.lineWidth=1.5; ctx.setLineDash([4,3]);
    var b0t=getVal('b0'), b1t=getVal('b1');
    ctx.beginPath();ctx.moveTo(tx(xmn),ty(b0t+b1t*xmn));ctx.lineTo(tx(xmx),ty(b0t+b1t*xmx));ctx.stroke();
    ctx.setLineDash([]);
    // fitted line
    ctx.strokeStyle='#38b49a'; ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(tx(xmn),ty(f.b0+f.b1*xmn));ctx.lineTo(tx(xmx),ty(f.b0+f.b1*xmx));ctx.stroke();
    // legend
    ctx.fillStyle='rgba(244,114,182,.6)';ctx.font='8px system-ui';ctx.textAlign='left';ctx.fillText('Vrai',PL+4,PT+10);
    ctx.fillStyle='#38b49a';ctx.fillText('Estimé',PL+4,PT+20);
    // labels
    ctx.fillStyle='rgba(255,255,255,.25)';ctx.textAlign='center';ctx.fillText('X₁',PL+(W-PL-PR)/2,H-2);

    // QQ plot
    var qq=document.getElementById('rl34-qq');
    if(qq){
      var qW=qq.parentElement.clientWidth/2-6||170, qH=90;
      qq.width=qW; qq.height=qH;
      var qctx=qq.getContext('2d');qctx.clearRect(0,0,qW,qH);
      var sorted=f.res.slice().sort(function(a,b){return a-b;});
      var n=sorted.length;
      var tq=sorted.map(function(_,i){return 4.91*(Math.pow((i+1-.5)/n,.14)-Math.pow(1-(i+1-.5)/n,.14));});
      var allv=sorted.concat(tq);
      var qmn=Math.min.apply(null,allv), qmx=Math.max.apply(null,allv);
      function qtx(v){return 6+(v-qmn)/(qmx-qmn)*(qW-12);}
      function qty(v){return 6+(1-(v-qmn)/(qmx-qmn))*(qH-16);}
      qctx.strokeStyle='rgba(255,255,255,.15)';qctx.lineWidth=1;
      qctx.beginPath();qctx.moveTo(qtx(qmn),qty(qmn));qctx.lineTo(qtx(qmx),qty(qmx));qctx.stroke();
      sorted.forEach(function(v,i){qctx.fillStyle='rgba(232,121,160,.75)';qctx.beginPath();qctx.arc(qtx(tq[i]),qty(v),2,0,2*Math.PI);qctx.fill();});
      qctx.fillStyle='rgba(255,255,255,.3)';qctx.font='8px system-ui';qctx.textAlign='left';qctx.fillText('QQ-plot résidus',4,qH-3);
    }

    // Residuals vs Fitted
    var rv=document.getElementById('rl34-rv');
    if(rv){
      var rW=rv.parentElement.clientWidth/2-6||170, rH=90;
      rv.width=rW; rv.height=rH;
      var rctx=rv.getContext('2d');rctx.clearRect(0,0,rW,rH);
      var rmn=Math.min.apply(null,f.res)-0.5, rmx=Math.max.apply(null,f.res)+0.5;
      var fmn=Math.min.apply(null,f.yhat)-0.5, fmx=Math.max.apply(null,f.yhat)+0.5;
      function rtx(v){return 6+(v-fmn)/(fmx-fmn)*(rW-12);}
      function rty(v){return 6+(1-(v-rmn)/(rmx-rmn))*(rH-16);}
      rctx.strokeStyle='rgba(255,255,255,.12)';rctx.lineWidth=1;
      rctx.beginPath();rctx.moveTo(6,rty(0));rctx.lineTo(rW-6,rty(0));rctx.stroke();
      f.yhat.forEach(function(v,i){rctx.fillStyle='rgba(126,200,227,.7)';rctx.beginPath();rctx.arc(rtx(v),rty(f.res[i]),2.5,0,2*Math.PI);rctx.fill();});
      rctx.fillStyle='rgba(255,255,255,.3)';rctx.font='8px system-ui';rctx.textAlign='left';rctx.fillText('Résidus vs Fitted',4,rH-3);
    }
  }

  function update() {
    var b0=getVal('b0'),b1=getVal('b1'),sg=getVal('sg');
    document.getElementById('rl34-b0v').textContent=b0;
    document.getElementById('rl34-b1v').textContent=b1;
    document.getElementById('rl34-sgv').textContent=sg;
    gen();
    var f=fit();
    var sig=Math.abs(f.t)>2.048?'*':'';
    var el=document.getElementById('rl34-res');
    if(el) el.textContent='β₀ = '+f.b0.toFixed(2)+'\nβ₁ = '+f.b1.toFixed(2)+' t='+f.t.toFixed(2)+sig+'\nR²  = '+f.r2.toFixed(3)+'\nσ   = '+f.se.toFixed(2);
    el.style.color = Math.abs(f.t)>2.048?'#7de8a0':'#f5a060';
    var rc=document.getElementById('rl34-code');
    if(rc) rc.textContent='lm(Y ~ X1, data=df)\nsummary(lm_obj)\nplot(lm_obj)  # QQ+résidus';
    draw(f);
  }

  ['b0','b1','sg'].forEach(function(id){
    var el=document.getElementById('rl34-'+id);
    if(el) el.addEventListener('input', update);
  });
  document.getElementById('rl34-regen').addEventListener('click', update);
  update();

  if(typeof ResizeObserver!=='undefined'){
    new ResizeObserver(update).observe(document.getElementById('rl34-cvs').parentElement);
  }
})();

(function(){
  var curLaw = 'norm';
  var P = { norm:{mu:0,sd:1}, t:{df:5}, chi2:{df:3}, binom:{n:20,p:0.3} };

  function erf(x){var t=1/(1+0.3275911*Math.abs(x));var y=1-t*(0.254829592+t*(-0.284496736+t*(1.421413741+t*(-1.453152027+t*1.061405429))))*Math.exp(-x*x);return x>=0?y:-y;}
  function normPDF(x,mu,sd){return Math.exp(-0.5*((x-mu)/sd)*((x-mu)/sd))/(sd*Math.sqrt(2*Math.PI));}
  function gamma(n){if(n===0.5)return Math.sqrt(Math.PI);if(n===1)return 1;if(n<0.5)return Math.PI/(Math.sin(Math.PI*n)*gamma(1-n));return (n-1)*gamma(n-1);}
  function tPDF(x,df){return gamma((df+1)/2)/(Math.sqrt(df*Math.PI)*gamma(df/2))*Math.pow(1+x*x/df,-(df+1)/2);}
  function chi2PDF(x,df){return x<=0?0:Math.pow(x,df/2-1)*Math.exp(-x/2)/(Math.pow(2,df/2)*gamma(df/2));}
  function binomPMF(k,n,p){if(k<0||k>n)return 0;var c=1;for(var i=0;i<k;i++)c=c*(n-i)/(i+1);return c*Math.pow(p,k)*Math.pow(1-p,n-k);}

  function getPts(){
    var p=P[curLaw], pts=[], xmn, xmx;
    if(curLaw==='norm'){ xmn=p.mu-4*p.sd;xmx=p.mu+4*p.sd;for(var i=0;i<=200;i++){var x=xmn+i*(xmx-xmn)/200;pts.push({x:x,y:normPDF(x,p.mu,p.sd)});}}
    else if(curLaw==='t'){xmn=-6;xmx=6;for(var i=0;i<=200;i++){var x=-6+i*12/200;pts.push({x:x,y:tPDF(x,p.df)});}}
    else if(curLaw==='chi2'){xmn=0;xmx=Math.max(12,p.df*3);for(var i=0;i<=200;i++){var x=i*xmx/200;pts.push({x:x,y:chi2PDF(x,p.df)});}}
    else{xmn=0;xmx=p.n;for(var k=0;k<=p.n;k++)pts.push({x:k,y:binomPMF(k,p.n,p.p)});}
    return pts;
  }

  function draw(){
    var cvs=document.getElementById('d35-cvs');
    if(!cvs)return;
    var W=cvs.parentElement.clientWidth-16||340,H=150;
    cvs.width=W;cvs.height=H;
    var ctx=cvs.getContext('2d');ctx.clearRect(0,0,W,H);
    var pts=getPts(),p=P[curLaw];
    var xmn=pts[0].x,xmx=pts[pts.length-1].x;
    var ymx=Math.max.apply(null,pts.map(function(pt){return pt.y;}))*1.12||0.1;
    var PL=35,PR=8,PT=10,PB=22;
    function tx(v){return PL+(v-xmn)/(xmx-xmn)*(W-PL-PR);}
    function ty(v){return PT+(1-v/ymx)*(H-PT-PB);}
    // grid
    for(var i=0;i<=4;i++){
      var yv=ymx*i/4;
      ctx.strokeStyle='rgba(255,255,255,.05)';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(PL,ty(yv));ctx.lineTo(W-PR,ty(yv));ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,.25)';ctx.font='8px monospace';ctx.textAlign='right';
      ctx.fillText(yv.toFixed(3),PL-2,ty(yv)+3);
    }
    for(var i=0;i<=5;i++){
      var xv=xmn+(xmx-xmn)*i/5;
      ctx.strokeStyle='rgba(255,255,255,.04)';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(tx(xv),PT);ctx.lineTo(tx(xv),H-PB);ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,.25)';ctx.font='8px monospace';ctx.textAlign='center';
      ctx.fillText(xv.toFixed(1),tx(xv),H-5);
    }
    // fill tail
    if(curLaw==='norm'){
      var crit=p.mu+1.96*p.sd;
      ctx.fillStyle='rgba(244,114,182,.15)';ctx.beginPath();
